async function importOrder(db:any,o:any,map:Map<string,any>){const id=externalId(o?.id);if(!id)return{ok:false};const sc=schedule(o),sp=clean(o?.specialist),st=sp?map.get(sp.toLocaleLowerCase('ru-RU')):null,amount=money(o?.price);const base:any={external_source:'hands',external_id:localExternalId(id),source:'Hands',client:clean(o?.client_name||o?.client)||'Без имени',phone:phones(o)||null,address:clean(o?.address)||'Адрес не указан',work:workText(o),city:cityFrom(o),status:localStatus(o),amount,original_amount:amount,scheduled_date:sc.scheduled_date,scheduled_time:sc.scheduled_time,master_name:sp||st?.full_name||null,source_updated_at:clean(o?.updated_at||o?.creation_time)||new Date().toISOString(),updated_at:new Date().toISOString(),sync_status:'synced'};if(st?.id)base.master_staff_id=st.id;const prev=await db.from('orders').select('id').eq('external_source','hands').eq('external_id',localExternalId(id)).maybeSingle();if(prev.error)throw new Error(`DB_LOOKUP: ${errText(prev.error)}`);if(prev.data){const q=await db.from('orders').update(base).eq('id',prev.data.id).select('id').single();if(q.error)throw new Error(`DB_UPDATE: ${errText(q.error)}`);return{ok:true,id:q.data.id,created:false}}const q=await db.from('orders').insert({...base,comment:externalComment(o)||null,created_by_vk_id:'hands-api'}).select('id').single();if(q.error)throw new Error(`DB_INSERT: ${errText(q.error)}`);return{ok:true,id:q.data.id,created:true}}
